func (v PropertiesValue) Equal(o attr.Value) bool {
	other, ok := o.(PropertiesValue)

	if !ok {
		return false
	}

	if v.state != other.state {
		return false
	}

	if v.state != attr.ValueStateKnown {
		return true
	}

	if !v.Breaks.Equal(other.Breaks) {
		return false
	}

	if !v.Categories.Equal(other.Categories) {
		return false
	}

	if !v.DirectionalityInterpretation.Equal(other.DirectionalityInterpretation) {
		return false
	}

	if !v.Distribution.Equal(other.Distribution) {
		return false
	}

	if !v.EmittedByDatasets.Equal(other.EmittedByDatasets) {
		return false
	}

	if !v.InterpretationMap.Equal(other.InterpretationMap) {
		return false
	}

	if !v.NullValueInterpretation.Equal(other.NullValueInterpretation) {
		return false
	}

	if !v.StatisticalType.Equal(other.StatisticalType) {
		return false
	}

	if !v.PropertiesType.Equal(other.PropertiesType) {
		return false
	}

	if !v.Unit.Equal(other.Unit) {
		return false
	}

	if !v.Values.Equal(other.Values) {
		return false
	}

	return true
}

